        public IWorkbook GetShiftReport(string companyGroupId, string companyId, string plantId, string plantName, string employeeId, string fromDate, string toDate, string EmpDoj)
        {
            try
            {//
                //if (employeeId == null)//
                //{
                //    Exception ex = new Exception("Please Select Employee First..");
                //    throw (ex);
                //}
                var reportUtility = new ReportUtility();
                var excelEngine = new ExcelEngine();
                var workbook = reportUtility.GetWorkbook(ref excelEngine, 1);
                workbook.Version = ExcelVersion.Excel2016;
                var sheet1 = workbook.Worksheets[0];

                CreateSheet(ref sheet1, "Shift Assignment", companyGroupId, companyId, plantId, plantName, employeeId, fromDate, toDate, EmpDoj);

                return workbook;

            }
            catch (Exception ex)
            {
                throw ex;
            }
        }
        void CreateSheet(ref IWorksheet sheet, string SheetName, string companyGroupId, string companyId, string plantId, string plantName, string employeeId, string fromDate, string toDate, string EmpDoj)
        {
            try
            {
                var row = 4;
                var reportUtility = new ReportUtility();
                sheet.Name = SheetName;
                var colLast = 1;
                var col = 1;
                var colAssigned = 0;
                var cisFixed = 0;
                var cRosterName = 0;
                var colEffective = 0;
                var endXlsCol = col;
                var colInTime = 0;
                var colOutTime = 0;
                var StartRow = 0;
                var colsingeldayshift = 0;
                var employee = _employeeInformationService.Find(employeeId);

                // Set Header
                reportUtility.SetMasterHeaderTextForShiftReport(ref sheet, row, 1, "Employee", 11);
                reportUtility.SetHeaderText(ref sheet, row, 3, "Code: " + employee.EmployeeCode + " Name: " + employee.EmployeeName + " DOJ: " + EmpDoj);
                sheet.Range[row, 2, row, 6].Merge();

                row += 2;

                reportUtility.SetHeaderText(ref sheet, row, col, "Effective date", ExcelHAlign.HAlignCenter); colEffective = col; col++;
                reportUtility.SetHeaderText(ref sheet, row, col, "Fixed/Roster", ExcelHAlign.HAlignCenter); cisFixed = col; col++;
                reportUtility.SetHeaderText(ref sheet, row, col, "Roster Name", ExcelHAlign.HAlignCenter); cRosterName = col; col++;
                reportUtility.SetHeaderText(ref sheet, row, col, "Assigned Shift", ExcelHAlign.HAlignCenter); colAssigned = col; col++;
                reportUtility.SetHeaderText(ref sheet, row, col, "Shift In Time", ExcelHAlign.HAlignCenter); colInTime = col; col++;
                reportUtility.SetHeaderText(ref sheet, row, col, "Shift Out Time", ExcelHAlign.HAlignCenter); colOutTime = col; col++;
                reportUtility.SetHeaderText(ref sheet, row, col, "Single Day Shift", ExcelHAlign.HAlignCenter); colsingeldayshift = col; col++;


                colLast = colAssigned;
                var ledgerData = GetShiftData(companyGroupId, companyId, plantId, employeeId, fromDate, toDate);
                row++;
                var colStart = 0;

                if (ledgerData.Rows.Count > 0)
                {
                    col = 1;
                    colStart = col;
                    StartRow = row;
                    for (int i = 0; i < ledgerData.Rows.Count; i++)
                    {
                        col = 1;
                        reportUtility.SetTextBdr(ref sheet, row, colInTime, ledgerData.Rows[i]["InTime"].ToString());
                        reportUtility.SetTextBdr(ref sheet, row, colOutTime, ledgerData.Rows[i]["outtime"].ToString());
                        reportUtility.SetTextBdr(ref sheet, row, colEffective, ledgerData.Rows[i]["effectivedate"].ToString());
                        reportUtility.SetTextBdr(ref sheet, row, cisFixed, ledgerData.Rows[i]["FixedORroster"].ToString());
                        reportUtility.SetTextBdr(ref sheet, row, cRosterName, ledgerData.Rows[i]["RosterName"].ToString());
                        reportUtility.SetTextBdr(ref sheet, row, colAssigned, ledgerData.Rows[i]["AssignedShift"].ToString());
                        reportUtility.SetTextBdr(ref sheet, row, colsingeldayshift, ledgerData.Rows[i]["SingleDayShift"].ToString());
                        row++;
                    }
                }
                row++;
                reportUtility.PlantHeader(ref sheet, colLast, "Shift Report", plantId);
                sheet.Range[5, 1, 5, colLast].Merge();
                reportUtility.PageSetup(ref sheet, 5, ExcelPageOrientation.Portrait);
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }
        private DataTable GetShiftData(string companyGroupId, string companyId, string plantId, string employeeId, string fromDate, string toDate)
        {
            var cmdText = @"	SELECT  EI.systemid,EI.employeecode, EI.employeename, Replace(CONVERT(VARCHAR(11), EI.DOJ, 106), ' ', '-') DOJ,
                                                FixedORroster=case when isnull(sdfx.username,'')<>'' then 'Fixed' else 'Roster' end,
												RosterName=sr.ShiftRosterDescription
                                    , SingleDayShift=case when  ESA.IsSingleDayShift =1 then 'Yes' else 'No' End,
                                              AssignedShift=isnull( sdfx.username,'')+isnull(sdrs.username,''),
                                                CONVERT(VARCHAR(5), isnull( sdfx.InTime,'')+isnull(sdrs.InTime,''), 108) InTime,                       
											   CONVERT(VARCHAR(5), isnull( sdfx.OutTime,'')+isnull(sdrs.OutTime,''), 108) outtime,
                                               Replace(CONVERT(VARCHAR(11), esa.effectivedate, 106), ' ', '-') effectivedate                                             										                                                 
                                        FROM   employeeinformation EI
 LEFT JOIN MST.ManpowerBudget mb ON mb.Id = ei.BudgetCode
                            LEFT JOIN ORG.Position PR ON MB.PositionId=PR.Id
                                        LEFT JOIN ORG.Department DEPT ON pr.DepartmentId=DEPT.Id
									    LEFT JOIN HKP.Designation DEG ON EI.GivenDesignationId=DEG.Id  
										left outer JOIN EmployeeShiftAssign ESA ON EI.SystemId = esa.EmpSystemID 
										LEFT JOIN dbo.ShiftRosterMaster SR ON ESA.RosterSystemID=SR.SystemID
										LEFT JOIN ShiftDefination SDFx ON ESA.FixSystemID = SDFx.SystemID
										LEFT JOIN ShiftDefination SDRs ON ESA.RosterStartShiftID = SDRs.SystemID
										where ei.SystemId='" + employeeId + @"'  AND ESA.EffectiveDate BETWEEN '" + fromDate + @"' AND '" + toDate + @"'
										order by esa.EffectiveDate";
            return _sqlRepository.GetDataTable(cmdText);
        }

