        void CountSheet(out int TotalSheet, params DataTable[] dts)
        {
            TotalSheet = 0;
            try
            {
                foreach (var dt in dts)
                {
                    if (dt.Rows.Count > 0)
                    {
                        TotalSheet++;
                    }
                }
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }
