        public IWorkbook GetHourlyLeave(string Name, string CompanyGroupId, string PlantId, string CompanyId, string PlantName, string FromDate, string ToDate)
        {

            #region declare
            clsReport objRpt = null;
            ReportUtility oru = new ReportUtility();
            DataSet dsHourlyOffDutyTag = null;
            DataTable dtHourlyOffDutyTag = null;
            DataSet dsCmp = null;
            DataSet dsFactory = null;
            clsStaticInfo objStatic = null;
            objStatic = new clsStaticInfo();
            string OTConsiderOn = string.Empty;
            #endregion
            try
            {
                ExcelEngine excelEngine = null;
                IApplication application = null;
                var workbook = oru.GetWorkbook(ref excelEngine, 1);
                workbook.Version = ExcelVersion.Excel2013;

                objRpt = new clsReport();
                string toDay = DateTime.Now.ToString("dd-MMM-yyyy");

                objRpt.GetHourLeaveReport(FromDate, ToDate, PlantId, CompanyId, CompanyGroupId, out dsHourlyOffDutyTag);
                dtHourlyOffDutyTag = dsHourlyOffDutyTag.Tables[0];

                objRpt.SelectedPlantWiseCompany(PlantId, out dsCmp);
                objRpt.SelectedPlant(PlantId, out dsFactory);
                excelEngine = new ExcelEngine();
                application = excelEngine.Excel;

                int xlsRow = 1, xlsCol = 1;
                int endXlsCol = 1;
                string FactoryName = "";
                string CmpName = "";
                var iName = 0;
                var iEmployeeCode = 0;
                //var iDepartment = 0;
                var iSubSection = 0;
                var iSection = 0;
                var iToDate = 0;
                var iFromDate = 0;
                var iDuration = 0;
                var iLine = 0;
                var iWorkDate = 0;
                var iDOJ = 0;
                var iDepartment = 0;
                var iDesignation = 0;
                var iDayStatus = 0;
                var iGender = 0;
                var iDurationDays = 0;
                var iapp = 0;
                var isl = 0;
                var SLNo = 1;
                var iReason = 1;
                var iApprovedType = 1;

                if (dsHourlyOffDutyTag.Tables[0].Rows.Count == 0)
                {
                    throw new CustomException("No Data Found....");
                }
                #region ManualOutTime

                IWorksheet sheet1 = null;

                sheet1 = workbook.Worksheets[0];
                xlsRow = 6;

                #region ------------------Column Header------------------
                isl = xlsCol;
                sheet1.Range[xlsRow, isl].Text = "SL";
                sheet1.Range[xlsRow, isl].ColumnWidth = 7;

                xlsCol += 1;
                iEmployeeCode = xlsCol;
                sheet1.Range[xlsRow, iEmployeeCode].Text = "Emp Code";
                sheet1.Range[xlsRow, iEmployeeCode].ColumnWidth = 10;

                xlsCol += 1;
                iName = xlsCol;
                sheet1.Range[xlsRow, iName].Text = "Emp Name";
